items(243,[
I('P000387','definition','Infinitesimal homogeneous spaces and infinitesimal torsors',r'A Lie algebra acts by vector fields; the space is homogeneous when evaluation at every point is onto, and principal when evaluation is an isomorphism. The preceding group definition requires a unique group element carrying one point to another.',r'Let \(a:\mathfrak g\to\mathfrak X(X)\) be a Lie algebra homomorphism. Transitivity means that \(a_x:\mathfrak g\to T_xX\) is surjective for each \(x\). An infinitesimal torsor has each \(a_x\) invertible and the inverse coframing smooth in the chosen topological category. This definition is infinitesimal: a global integrated action can still have discrete stabilizers.',r'The principal-space language was already published by \citet[\S3]{gelfandkazhdan1971geometry}, received 5 June 1971. Its precise topological formulation is given in \citet[Definition 2.1]{bernsteinrosenfeld1973homogeneous}. The 15 November lecture explicitly refers to the earlier announcement.',r'this is an established definition in formal geometry. The terms principal Lie-algebra space and principal group space should not be interchanged without a globalization and stabilizer condition.',publication_match='exact',refs=GK+BR),
I('P000387','claim','Finite-dimensional Lie algebras integrate locally, not automatically globally',r'The underlined answer to when one can pass to a group is: when the Lie algebra is finite-dimensional. No completeness hypothesis is stated.',r'A smooth action of a finite-dimensional real Lie algebra on a finite-dimensional manifold integrates locally. A global action with these infinitesimal generators requires their completeness; finite-dimensionality by itself is insufficient. Even a complete infinitesimal torsor need not be a free torsor for the simply connected integrating group.',r'This is a qualification of classical Lie integration, explicitly stated as local integration in \citet[Introduction, pp.~108--109]{bernsteinrosenfeld1973homogeneous}. It is not a new globalization theorem in the notebook.',r'the local reading is correct; the unrestricted global reading is false. No classification of globalizations is inferred from the shorthand.',reconstruction=r'\ours\ For the global claim, take \(X=(0,1)\) and the action of \(\mathbb R\) generated by \(\partial_x\). Evaluation is an isomorphism everywhere, but its integral curve \(x+t\) leaves \(X\) in finite time. For the freeness issue, translations by \(\mathbb R\) on \(\mathbb R/\mathbb Z\) have isomorphic evaluation maps and stabilizer \(\mathbb Z\).',literal_correctness='correct with missing hypotheses',publication_match='partial',refs=BR),
I('P000387-P000388','definition','Formal vector fields and the origin-fixing formal coordinate group',r'\(W_n\) consists of formal vector fields. The notes say that its group does not exist because one cannot move; the subalgebra \(L_0\) of fields with zero constant term does integrate and has codimension \(n\). Hamiltonian and volume-preserving variants are mentioned.',r'For \(n\geq1\), let \(W_n=\operatorname{Der}_{\mathbb R}\mathbb R[[x_1,\ldots,x_n]]\) with its coefficient topology and continuous bracket. The subalgebra \(L_0=\{\sum a_i\partial_i:a_i(0)=0\}\) has vector-space codimension \(n\). The group \(G_n^0\) of invertible formal substitutions fixing the origin is the inverse limit of its finite-jet groups and has Lie algebra \(L_0\) in that category. A general formal series cannot be translated by a nonzero real constant by an unrestricted numerical substitution.',r'These objects are used in \citet[\S1]{gelfandfuchs1970formal} and \citet[\S3]{gelfandkazhdan1971geometry}; the formal-group and transitive-subalgebra conventions are made explicit in \citet[\S\S4--5]{bernsteinrosenfeld1973homogeneous}. They precede the lecture.',r'the distinction between full formal vector fields and the origin-fixing formal group remains essential. The phrase that no group exists is category dependent; it is not a theorem excluding formal groupoids or every infinite-dimensional integration concept.',literal_correctness='correct with missing hypotheses',publication_match='exact',refs=GF+GK+BR),
I('P000388','theorem','Automorphisms of the Lie algebra of formal vector fields',r'The notebook states that the Lie algebra of the automorphism group of \(W_n\) is \(L_0\). It compares this with quotienting an ordinary Lie algebra by its centre.',r'Over a characteristic-zero field, every continuous Lie algebra automorphism of \(W_n\) is induced by an invertible origin-fixing formal coordinate substitution. Thus, over \(\mathbb R\), the automorphism group with the formal-coordinate, finite-jet group structure has Lie algebra \(L_0\). This is a statement about that topological group, not an unrestricted identification with all algebraic derivations of \(W_n\).',r'\citet[Theorem 1 and \S3, Theorem 2(1)]{rudakov1969automorphisms} proved preservation of the formal filtration and the coordinate-change description; the paper was received 18 December 1968 and published in Russian in 1969. Theorem 2 also treats the divergence-free, Hamiltonian and contact series. This is prior work, not an unpublished 1971 conjecture.',r'the continuous formal-coordinate classification is established. The notebook comparison with quotient by the centre describes inner automorphisms in the classical case; it does not identify the entire automorphism algebra for arbitrary finite-dimensional Lie algebras.',literal_correctness='correct with missing hypotheses',publication_match='exact',refs=RU),
I('P000388','construction','The formal frame bundle as a principal Wn-space',r'For an arbitrary \(n\)-manifold \(M\), the space \(S(M)\) of jets of local coordinate systems is declared a principal \(W_n\)-space. Equivalence of charts is written as all derivatives of their transition map being zero.',r'For a smooth \(n\)-manifold \(M\), let \(S(M)\) consist of infinite jets at \(0\) of local diffeomorphisms \((\mathbb R^n,0)\to(M,x)\), for all \(x\). It has a canonical smooth \(W_n\)-valued coframing satisfying the Maurer--Cartan equation, equivalently a principal infinitesimal \(W_n\)-space structure. Two charts define the same jet when their coordinate difference is flat, or their transition has the identity infinite jet. The transition itself cannot have all derivatives zero, since its first derivative is invertible.',r'\citet[\S3 and \S4, Proposition 1]{gelfandkazhdan1971geometry} announced this construction before the lecture; \citet[Theorem 4.1]{bernsteinrosenfeld1973homogeneous} give a detailed construction and proof in the finite-coordinate category.',r'the formal frame construction is established. The chart-equivalence sentence is a mathematical slip faithfully reproduced by the transcription; correcting it does not require guessing any cancelled words.',literal_correctness='false as written',publication_match='exact',refs=GK+BR),
I('P000388','question','Other substantive principal Wn-spaces',r'The final sentence asks whether there are other substantive principal homogeneous spaces, after constructing \(S(M)\). It gives no meaning for substantive or for equivalence of examples.',r'The identifiable topic is the possible existence or classification of principal infinitesimal \(W_n\)-spaces beyond formal frame spaces. A definite classification problem requires specifying the category, local or global equivalence, permitted quotients and what counts as arising from a manifold. These data are absent, so no unique stronger proposition is reconstructed.',r'The later theory of \citet[\S\S2, 4--7]{bernsteinrosenfeld1973homogeneous} treats homogeneous spaces and geometric structures systematically. Searches for principal \(W_n\)-spaces and classification did not identify a theorem matching this qualitative question.',r'the particular intended question remains unidentified. This is a limit of the notebook formulation and the checked literature, not evidence that a precise classification problem is open.',**{'class':'F'},literal_correctness='not determinable',publication_match='thematic only',verification='unresolved lead',refs=BR,confidence='low'),
I('P000389-P000390','construction','The characteristic chain map from Lie algebra cochains',r'A skew multilinear form on \(W_n\) is evaluated on the vectors corresponding to tangent vectors of \(S(M)\). The resulting map is said to commute with the differentials. The printed exponent \(s+t=1\) is also visible in the scan.',r'For a principal infinitesimal \(\mathfrak g\)-space with Maurer--Cartan coframing \(\theta\), a continuous Chevalley--Eilenberg cochain \(c\) gives the differential form \(\Phi(c)(v_1,\ldots,v_q)=c(\theta v_1,\ldots,\theta v_q)\). With matching bracket and Maurer--Cartan signs, \(d\Phi(c)=\Phi(d_{\mathrm{CE}}c)\), giving \(H^*_{\mathrm{cont}}(\mathfrak g)\to H^*_{\mathrm{dR}}(S)\). For \(W_n\), continuous scalar cochains depend on finitely many jet coordinates.',r'This is the cohomological construction in \citet[\S4]{gelfandkazhdan1971geometry}, whose note is explicitly cited on the notebook page. A complete statement and proof are in \citet[\S3, Theorem 3.1]{bernsteinrosenfeld1973homogeneous}.',r'the characteristic map is established. The malformed exponent must be emended together with a consistent left/right convention; its exact intended sign cannot be settled from the two horizontal strokes alone.',reconstruction=r'Using the convention \(d\theta+\tfrac12[\theta,\theta]=0\) and numbering arguments from 1, the bracket term is \(\sum_{s<t}(-1)^{s+t}c([\xi_s,\xi_t],\xi_1,\ldots,\widehat\xi_s,\ldots,\widehat\xi_t,\ldots,\xi_{q+1})\). Opposite action conventions change the displayed sign consistently. No literal equality sign belongs in this exponent.',literal_correctness='false as written',publication_match='exact',refs=GK+BR),
I('P000389-P000390','definition','Bernstein’s finite-coordinate differential calculus on jet towers',r'After the heading I. Bernstein, an infinite-dimensional manifold is defined as an inverse limit of finite-dimensional manifolds with onto maps; functions are the union of the finite-stage function rings. The de Rham differential is then written by its vector-field formula.',r'For the jet towers in question one may use inverse systems whose sufficiently high stages are compatible affine bundles over a fixed finite stage. Their inverse limits admit charts modelled on \(\mathbb R^{\mathbb N}\). Scalar functions and forms are locally pulled back from a finite stage; vector fields and the exterior differential are defined compatibly. The local finite-stage condition is more general than requiring a single global stage for every smooth function. Arbitrary surjective inverse systems alone do not guarantee this manifold structure.',r'Bernstein’s intervention is developed with Rosenfeld in \citet[\S1, Definitions 1.1--1.10, Proposition 1.1 and Example 1.1]{bernsteinrosenfeld1973homogeneous}, received 29 March 1973 and published in 1973. That paper explicitly distinguishes its smooth finite-coordinate category from an arbitrary inverse limit.',r'the construction is established for the formal jet spaces used here. The omitted local and bundle hypotheses are material; the statement should not be exported as a definition of all infinite-dimensional smooth manifolds.',**{'class':'A'},speaker='I. N. Bernstein (intervention)',publication_match='exact',refs=BR),
I('P000390','claim','The formal Lie algebra is an inverse limit as a vector space',r'The Lie algebra is described parenthetically as a projective limit of finite-dimensional ones with the corresponding topology. Taken literally as finite-dimensional Lie algebra quotients, this excludes the main example.',r'In the formal-vector-field setting the underlying topological vector space is an inverse limit of finite-dimensional jet spaces, and the Lie bracket is continuous. The finite coefficient truncations of \(W_n\) are not Lie algebra quotients: order filtrations are not ideals because a constant vector field lowers vanishing order. No projective system of these truncated Lie algebras is required.',r'\citet[\S0.1]{gelfandfuchs1970formal} use the topological vector-space formulation, and \citet[\S2, preceding Definition 2.1]{bernsteinrosenfeld1973homogeneous} specify that \(\mathfrak g\) is modelled on \(\mathbb R^k\) or \(\mathbb R^{\mathbb N}\) as a vector space.',r'the continuous Lie algebra formulation is standard. The literal finite-dimensional Lie-quotient reading is an error; finite jet vector spaces suffice for the subsequent continuous-cochain construction.',reconstruction=r'\ours\ In one variable, \([\partial_x,x^{k+1}\partial_x]=(k+1)x^k\partial_x\). Thus the fields vanishing to order at least \(k+1\) are not stable under bracketing with all of \(W_1\), and the proposed quotient bracket is not well defined.',literal_correctness='false as written',publication_match='exact',refs=GF+BR,speaker='I. N. Bernstein (intervention)'),
I('P000390-P000392','construction','Relative cochains and descent of basic forms',r'The relative complex consists of cochains \(c\) for which both \(c\) and \(dc\) vanish when an argument lies in \(\mathfrak p\). A form on the base is obtained by lifting tangent vectors; independence of the point in the fibre is asserted.',r'The relative complex is \(C^*(\mathfrak g,\mathfrak p)=\{c:i_Xc=i_Xdc=0\text{ for every }X\in\mathfrak p\}\), equivalently horizontal and \(\mathfrak p\)-invariant cochains. For a compatible bundle \(P\to X\) of principal infinitesimal spaces whose fibres are connected principal \(\mathfrak p\)-spaces, the characteristic forms descend and give \(C^*(\mathfrak g,\mathfrak p)\to\Omega^*(X)\). With a disconnected structure group \(H\), one must require invariance under all of \(H\), as well as horizontality for its Lie algebra.',r'The relative-complex definition is classical. The homogeneous-space descent in the intervention is formulated precisely by \citet[\S3, Proposition 3.2, Theorem 3.2 and Remark 3.2]{bernsteinrosenfeld1973homogeneous}; Proposition 3.2 explicitly assumes connected fibres.',r'the construction is established with those hypotheses. Horizontality gives independence of lifts, while infinitesimal invariance gives independence only within a connected fibre component; these are different steps.',**{'class':'A'},speaker='I. N. Bernstein (intervention)',publication_match='exact',refs=BR),
I('P000391','claim','Relative Lie algebra cohomology need not equal the cohomology of a homogeneous space',r'The line after the relative-complex definition identifies its cohomology with that of the quotient in the classical case, without compactness or other comparison hypotheses.',r'For a Lie group \(G\) and closed subgroup \(H\), relative cochains describe suitable \(G\)-invariant differential forms on \(G/H\), including invariance under disconnected isotropy components when necessary. Their inclusion in all differential forms is not generally a quasi-isomorphism. The characteristic construction gives a homomorphism on cohomology; equality requires an additional comparison theorem.',r'\citet[Theorem 3.2 and Remark 3.2]{bernsteinrosenfeld1973homogeneous} assert the homomorphism, not a general isomorphism. The notebook’s unrestricted equality is therefore not part of the verified published result.',r'the unrestricted equality is false, already in dimension one. This is an elementary correction, not an unresolved comparison problem.',reconstruction=r'\ours\ Let \(G=(\mathbb R,+)\) and \(H=\{0\}\). The abelian one-dimensional Lie algebra has \(H^1(\mathfrak g;\mathbb R)=\mathbb R\), represented by its nonzero linear functional. Its corresponding invariant form on \(G\) is \(dx\), but \(dx=d(x)\), so \(H^1_{\mathrm{dR}}(\mathbb R)=0\).',literal_correctness='false as written',publication_match='partial',refs=BR,speaker='I. N. Bernstein (intervention)'),
I('P000392','theorem','Removing linear frames leaves a space homotopy equivalent to the manifold',r'\(S(M)\) is said to be homotopy equivalent to the first-frame bundle, while \(S(M)/GL(n,\mathbb R)\) is homotopy equivalent to \(M\). A marginal line mentions a map \(M\to S(M)\); later, choices are associated with a connection.',r'The projection from formal frames to first frames has contractible higher-jet fibres. Similarly, the bundle \(S(M)/GL(n,\mathbb R)\to M\) has contractible fibre, and is a homotopy equivalence for a smooth paracompact manifold. A connection provides a formal exponential section of this quotient. A section of the full frame space would also choose a frame of \(TM\) and generally does not exist.',r'The formal-coordinate construction is in \citet[\S3]{gelfandkazhdan1971geometry}. The contractible higher-jet-fibre argument is made explicit in \citet[\S8, Theorems 8.3--8.4]{bernsteinrosenfeld1973homogeneous}.',r'the two homotopy statements are established. The unclear marginal word is left unresolved; if the marginal map means a section, its target must be the quotient unless a global framing has been assumed.',literal_correctness='correct with missing hypotheses',publication_match='exact',refs=GK+BR,speaker='I. N. Bernstein (intervention)'),
I('P000392,P000394','theorem','The truncated characteristic polynomial ring in relative Wn-cohomology',r'The relative cohomology is described by generators \(\psi_1,\ldots,\psi_n\), written as having degree \(2n\), with products of degree greater than \(2n\) zero. The later page cites Gelfand and Fuks, Izvestiya, 1971.',r'With real coefficients and continuous cochains, the group-relative characteristic complex gives \[H^*(W_n,GL(n,\mathbb R))\simeq\mathbb R[c_1,\ldots,c_n]/I_{>2n},\qquad |c_i|=2i.\] Here \(I_{>2n}\) is the ideal generated by monomials of cohomological degree greater than \(2n\). Group-relative means horizontality for \(\mathfrak{gl}_n\) and invariance under the full linear group. The polynomial generators have different degrees; the quotient is essential.',r'The underlying formal-vector-field computation was published by \citet{gelfandfuchs1970formal}, received 4 November 1969 and published in Russian in 1970. Its English printing carries 1971 copyright, explaining the notebook date. The exact relative statement is \citet[Theorem 10.2]{bernsteinrosenfeld1973homogeneous}; see also \citet[\S2, pp.~125--126]{bott1976characteristic}.',r'the truncated relative ring is established. It is not the untruncated cohomology of \(BGL_n\), and replacing every generator degree by \(2n\) loses the result.',literal_correctness='false as written',publication_match='exact',refs=GF+BR+['bott1976characteristic'],speaker='I. N. Bernstein (intervention)'),
I('P000392','construction','Chern–Weil classes from formal frames and the role of a connection',r'The images of the generators are linked to Chern classes of the tangent bundle and to Pontryagin classes. Forms are canonical upstairs; nonuniqueness appears when a connection is chosen to obtain forms on \(M\).',r'Normalize the formal curvature generators so that their characteristic images are \(c_i(TM\otimes_{\mathbb R}\mathbb C)\) in real cohomology. Odd Chern classes of a complexified real bundle vanish over \(\mathbb R\), and \(p_i(TM)=(-1)^i c_{2i}(TM\otimes\mathbb C)\) in the standard convention. Pulling a fixed universal cocycle back along a formal exponential section gives a differential-form representative; changing the connection changes the representative by an exact form, not its cohomology class.',r'This is the classical Chern--Weil construction expressed through \citet{gelfandkazhdan1971geometry}. The normal-bundle version is identified in \citet[Theorem 10.5]{bernsteinrosenfeld1973homogeneous}, whose normalization sends its generator \(c_{2i}\) directly to \(p_i\). \citet[\S4]{bott1976characteristic} verifies the corresponding characteristic map.',r'the characteristic classes are established and independent of the auxiliary connection. The notebook’s Chern/Pontryagin wording should be read with complexification and normalization stated, not as two unrelated sets of real tangent-bundle classes.',literal_correctness='correct with missing hypotheses',publication_match='exact',refs=GK+BR+['bott1976characteristic'],speaker='I. N. Bernstein (intervention)'),
I('P000393-P000394','construction','Formal transverse frames of a foliation',r'For a codimension-\(n\) foliation, transverse formal coordinates define \(S_{\mathcal F}(M)\); the notes stress that this is not itself supplied with the claimed natural principal Lie-algebra action. Adapted full coordinates define \(S^{\prime}_{\mathcal F}(M)\), a principal \(W_{N,n}\)-space, with a leaf-tangent subalgebra \(L\) and quotient \(W_n\).',r'Let \(\mathcal F\) be a regular smooth foliation of codimension \(n\) on an \(N\)-manifold. In formal coordinates \((y,z)\), with \(y\in\mathbb R^n\) transverse, \(W_{N,n}\) consists of fields whose \(y\)-components depend only on \(y\). The ideal \(L\) of fields tangent to the standard leaves has quotient \(W_{N,n}/L\simeq W_n\). Adapted formal frames give a homogeneous pair with isotropy \(L\), hence \(C^*(W_n)=C^*(W_{N,n},L)\to\Omega^*(S_{\mathcal F}(M))\). Passing to full linear-group basic cochains yields the normal-bundle characteristic map on \(M\), since \(S_{\mathcal F}(M)/GL_n\to M\) has contractible higher-jet fibres.',r'The characteristic-class programme was announced by Bernstein and Rosenfeld in 1972, as recorded in reference [3] and the introduction of their detailed \citet[\S\S6, 8--10]{bernsteinrosenfeld1973homogeneous}. That full paper, received 29 March 1973, verifies the homogeneous-space and characteristic-map mechanism. The present notebook records Bernstein’s 1971 intervention.',r'this construction is established for regular smooth foliations. The transverse quotient and the adapted full-frame principal space have different roles; merely postulating a \(W_n\)-action on the former would omit the actual descent argument.',**{'class':'A'},speaker='I. N. Bernstein (intervention)',publication_match='exact',refs=BR),
I('P000392-P000394','theorem','Bott vanishing for the real normal bundle',r'The explicit formula kills products of the \(\psi_i\) of degree \(>2n\). The following sentence appears to change this to \(\geq2n\), although the additional stroke is uncertain; the result is named Bott’s theorem.',r'For a regular \(C^\infty\) foliation of real codimension \(n\) with normal bundle \(\nu=TM/T\mathcal F\), every monomial in the real Pontryagin classes of \(\nu\) having total cohomological degree strictly greater than \(2n\) vanishes. Equivalently, the corresponding real Chern classes of \(\nu\otimes\mathbb C\) satisfy the truncated polynomial relations. This gives no blanket vanishing in degree exactly \(2n\), and does not assert vanishing of integral torsion classes.',r'This is the prior obstruction of \citet{bott1970integrability}, from the Berkeley symposium of July 1968, printed in 1970. The formal-cohomology deduction is explicit in \citet[Theorem 10.2, Theorem 10.5 and Corollary 10.1]{bernsteinrosenfeld1973homogeneous} and is revisited by \citet[\S4]{bott1976characteristic}.',r'the strict-degree real-cohomology theorem is established. The scan does not justify silently adopting the stronger boundary inequality; the preceding clear formula supplies the mathematically correct bound.',literal_correctness='correct with missing hypotheses',publication_match='exact',refs=BO+BR,speaker='I. N. Bernstein (intervention)'),
I('P000394','problem','Characteristic obstruction to homotoping a distribution to a foliation',r'The last sentence before Arnold’s new heading calls the vanishing relation an obstruction to being homotopically integrable.',r'Given a smooth codimension-\(n\) subbundle \(D\subset TM\), ask whether it is homotopic through subbundles of the same rank to the tangent distribution of a regular foliation. A necessary condition is that every real Pontryagin monomial of \(TM/D\) of degree \(>2n\) vanish. The statement is an obstruction, not a sufficient criterion.',r'This is the same integrability problem and Bott obstruction already indexed as GP-1970-26, occurrences 1970-206.1 and 1970-206.2. The notebook supplies a new formal-cohomology derivation of the known obstruction \citep{bott1970integrability}; its characteristic interpretation is verified in \citet[\S4]{bott1976characteristic}.',r'the necessary condition is established and recurs here. No claim of a complete classification of integrable homotopy classes is made on the basis of the literature checked for this occurrence.',reconstruction=r'\ours\ A homotopy \(D_t\) defines a vector bundle over \(M\times[0,1]\); its quotient bundles at the endpoints are isomorphic. Their Pontryagin classes therefore agree. If \(D_1\) is integrable, Bott vanishing for \(TM/D_1\) gives the stated necessary condition for \(TM/D_0\).',problem='GP-1970-26',publication_match='exact',refs=BO,speaker='I. N. Bernstein (intervention)')
])
problems([{'id':'GP-1970-26','title':'Topological obstruction to integrability of plane distributions','statement':r'For a smooth codimension-\(n\) distribution \(D\subset TM\), determine whether it can be homotoped through distributions of the same rank to an integrable distribution. Bott’s necessary condition is the vanishing over \(\mathbb R\) of every Pontryagin monomial of \(TM/D\) whose cohomological degree exceeds \(2n\).','occurrences':['1970-206.1','1970-206.2','1971-243.17'],'status':r'As of November 2026, the Bott obstruction is established. The present occurrence supplies its formal-vector-field interpretation; the checked sources do not turn this necessary condition into a general sufficiency criterion \citep{bott1970integrability,bott1976characteristic}.','status_date':'2026-11','refs':BO}])
